import{_ as a,o as t,c as l,a7 as i}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Life Leaf Data Deletion","description":"Official data-deletion instructions for Life Leaf.","frontmatter":{"title":"Life Leaf Data Deletion","description":"Official data-deletion instructions for Life Leaf.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/life-leaf.md","filePath":"data-deletion/life-leaf.md"}'),o={name:"data-deletion/life-leaf.md"};function r(d,e,n,s,f,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="delete-life-leaf-data" tabindex="-1">Delete Life Leaf Data <a class="header-anchor" href="#delete-life-leaf-data" aria-label="Permalink to &quot;Delete Life Leaf Data&quot;">​</a></h1><p>Life Leaf has no online account or developer-operated cloud database. Its diary records and settings are stored on your device.</p><h2 id="delete-individual-entries" tabindex="-1">Delete individual entries <a class="header-anchor" href="#delete-individual-entries" aria-label="Permalink to &quot;Delete individual entries&quot;">​</a></h2><p>Use an entry&#39;s delete action and confirm the request. You can restore an item from Trash or permanently delete it using the controls provided there. Archived entries remain stored until you restore or delete them.</p><h2 id="delete-all-local-data" tabindex="-1">Delete all local data <a class="header-anchor" href="#delete-all-local-data" aria-label="Permalink to &quot;Delete all local data&quot;">​</a></h2><p>Use Life Leaf&#39;s delete-all-data control and complete its confirmation, or clear Life Leaf storage in Android system settings. Uninstalling the app also removes its app-local information.</p><h2 id="delete-files-outside-the-app" tabindex="-1">Delete files outside the app <a class="header-anchor" href="#delete-files-outside-the-app" aria-label="Permalink to &quot;Delete files outside the app&quot;">​</a></h2><p>Clearing app data or uninstalling does not remove <code>.lifeleaf</code> backups, attachments exported separately, or other files saved or shared outside Life Leaf. Delete those copies from every destination where you stored them.</p><p>Because the developer holds no account or cloud copy of your diary, emailing support cannot delete information stored only on your device.</p>',9)])])}const u=a(o,[["render",r]]);export{h as __pageData,u as default};
